/**
 * Creates Yoruba (yo) translation files for remaining content pages:
 * bank-runs, wallets, buy, lightning, stickers, postcards, signs, flyers, get-involved
 * Uses read-and-override approach for files with many proper noun keys
 */
const fs = require('fs');
const path = require('path');
const i18nDir = path.join(__dirname, '..', '..', 'i18n');
const lang = 'yo';
const today = '2026-04-12';
const meta = { "@metadata": { "authors": ["Satoshi"], "last-updated": today, "locale": lang } };

function readEn(file) {
	return JSON.parse(fs.readFileSync(path.join(i18nDir, 'en', file), 'utf8'));
}
function writeFile(relPath, data) {
	const filePath = path.join(i18nDir, lang, relPath);
	fs.mkdirSync(path.dirname(filePath), { recursive: true });
	fs.writeFileSync(filePath, JSON.stringify(data, null, '\t') + '\n', 'utf8');
	console.log(`CREATED: ${filePath}`);
}
function createFromEn(enFile, outFile, overrides) {
	const data = { ...readEn(enFile), ...overrides };
	data["@metadata"] = meta;
	writeFile(outFile, data);
}

